function fmt(n:number,d=0){return new Intl.NumberFormat("es-EC",{minimumFractionDigits:d,maximumFractionDigits:d}).format(n)}
const money=(n:number)=>`$${fmt(n,0)}`;
const ropFor=(i:Interval)=>calculateRop(i.endDepth-i.startDepth,i.minutes/60);
const isoDate=(offsetDays=0)=>{const date=new Date();date.setUTCDate(date.getUTCDate()+offsetDays);return date.toISOString().slice(0,10)};
const normalize=(value:string)=>value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
function downloadCsv(filename:string,headers:string[],rows:Array<Array<string|number>>){
  const escape=(value:string|number)=>`"${String(value).replaceAll('"','""')}"`;
  const csv=`\uFEFF${[headers,...rows].map(row=>row.map(escape).join(",")).join("\n")}`;
  const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));
  const link=document.createElement("a");link.href=url;link.download=filename;link.click();URL.revokeObjectURL(url);
}

