function Analytics({tenantId}:{tenantId:TenantId}){
  const dataset=useMemo(()=>getDemoBiDataset(tenantId),[tenantId]);
  const snapshot=useMemo(()=>buildOperationalSnapshot(dataset,undefined,7),[dataset]);
  const catalog=dataset.crowns.filter(crown=>crown.diameter==="HQ");
  if(!dataset.drillholes.length)return <EmptyTenant/>;
  const max={rop:Math.max(...catalog.map(c=>c.historicalRop),1),life:Math.max(...catalog.map(c=>c.historicalLife),1),stock:Math.max(...catalog.map(c=>c.stock-c.reserved),1),evidence:Math.max(...catalog.map(c=>c.observations),1)};
  const costs=catalog.map(c=>c.historicalCost).filter(Boolean),minCost=costs.length?Math.min(...costs):1;
  const palette=["#d7ff43","#56c7ff","#ff9f43"];
  const radar={animationDuration:450,tooltip:{},legend:{data:catalog.map(c=>c.product),bottom:0,textStyle:{color:"#89969e"}},radar:{indicator:[{name:"ROP",max:5},{name:"Bajo costo",max:5},{name:"Vida",max:5},{name:"Disponibilidad",max:5},{name:"Evidencia",max:5}],splitLine:{lineStyle:{color:"#334048"}},splitArea:{areaStyle:{color:["transparent"]}},axisName:{color:"#a1adb4"}},series:[{type:"radar",data:catalog.map((c,index)=>({name:c.product,value:[c.historicalRop/max.rop*5,minCost/c.historicalCost*5,c.historicalLife/max.life*5,(c.stock-c.reserved)/max.stock*5,c.observations/max.evidence*5],lineStyle:{color:palette[index]},itemStyle:{color:palette[index]},areaStyle:{color:index===0?"rgba(215,255,67,.10)":"transparent"}}))}]};
  const util={animationDuration:450,tooltip:{trigger:"axis"},grid:{left:44,right:20,top:20,bottom:30},xAxis:{type:"category",data:snapshot.daily.map(day=>day.date.slice(8)+" Ago"),axisLabel:{color:"#78858d"}},yAxis:{type:"value",min:40,max:100,axisLabel:{color:"#78858d",formatter:"{value}%"},splitLine:{lineStyle:{color:"#263039"}}},series:[{type:"line",data:snapshot.daily.map(day=>day.utilization),smooth:true,areaStyle:{color:"rgba(65,214,163,.12)"},lineStyle:{color:"#41d6a3",width:3},itemStyle:{color:"#41d6a3"},markLine:{data:[{yAxis:70}],lineStyle:{color:"#f4b942",type:"dashed"}}}]};
  const fastest=catalog.slice().sort((a,b)=>b.historicalRop-a.historicalRop)[0],cheapest=catalog.slice().sort((a,b)=>a.historicalCost-b.historicalCost)[0];
  return <><div className="filterbar"><div><Filter/>Filtros avanzados</div><label>Diámetro<select><option>HQ</option></select></label><label>Taladro<select><option>Todos</option></select></label><label>Corona<select><option>Todas</option></select></label><label>Periodo<select><option>Últimos 7 días</option></select></label></div><div className="split-grid"><section className="panel"><PanelHead title="Perfil comparativo de coronas" subtitle="ROP, costo, vida, stock y evidencia · normalizado"/><EChart option={radar} className="chart chart-lg" ariaLabel="Perfil normalizado de coronas HQ"/></section><section className="panel"><PanelHead title="Tendencia de utilización" subtitle="Meta operacional: 70% · datos diarios reales"/><EChart option={util} className="chart chart-lg" ariaLabel="Utilización diaria comparada con meta de 70 por ciento"/></section></div><section className="panel"><PanelHead title="Lecturas clave" subtitle="Señales calculadas del periodo"/><div className="insight-cards"><div><TrendingUp/><b>{fastest?.product} lidera en velocidad</b><p>{fastest&&cheapest?`${fmt((fastest.historicalRop/cheapest.historicalRop-1)*100,1)}% más ROP que ${cheapest.product}, con costo histórico diferente.`:"Sin evidencia suficiente."}</p></div><div><CircleDollarSign/><b>{cheapest?.product} minimiza costo</b><p>{cheapest?`USD ${cheapest.historicalCost}/m y ${cheapest.stock-cheapest.reserved} unidades netas disponibles.`:"Sin evidencia suficiente."}</p></div><div><AlertTriangle/><b>La dureza coincide con menor ROP</b><p>En dureza 4–5 el ROP medio cambia {fmt(snapshot.hardnessRopChangePct,1)}% frente a dureza 1–3; es correlación operacional, no causalidad geológica.</p></div></div></section></>;
}

