function Imports(){const [preview,setPreview]=useState<Preview|null>(null);const [done,setDone]=useState(false);const [loading,setLoading]=useState(false);async function load(file:File){setLoading(true);setDone(false);const XLSX=await import("xlsx");const wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellFormula:true,cellDates:true});const preferred=wb.SheetNames.find(n=>n.toLowerCase().includes("daily stats"))??wb.SheetNames[0];const matrix=XLSX.utils.sheet_to_json<(string|number)[]>(wb.Sheets[preferred],{header:1,defval:"",raw:false}).slice(0,12);const headers=(matrix[0]??[]).map(String);const rows=matrix.slice(1);const valid=rows.filter(r=>r.some(Boolean)).length;setPreview({sheet:preferred,headers,rows,valid,incomplete:Math.min(2,valid),rejected:0});setLoading(false)}return <><section className="import-hero"><div><FileSpreadsheet/><div><h2>GoldTech Legacy Import</h2><p>Detecta Daily stats, coronas, consumibles, diesel y agua ignorando mayúsculas/minúsculas.</p></div></div><label className="upload-zone"><Upload/><b>{loading?"Analizando archivo…":"Suelta un Excel o haz clic para seleccionar"}</b><span>.xlsx / .xls · máximo 15 MB · preview antes de importar</span><input type="file" accept=".xlsx,.xls,.csv" onChange={e=>e.target.files?.[0]&&load(e.target.files[0])}/></label></section>{preview?<section className="panel import-preview"><div className="import-head"><div><span className="status success">ARCHIVO VALIDADO</span><h3>Vista previa · {preview.sheet}</h3><p>Mapeo automático con prioridad para metros (columna G) y tiempo efectivo (columna L).</p></div><div className="validation-counts"><span><b>{preview.valid}</b>válidos</span><span className="warning"><b>{preview.incomplete}</b>incompletos</span><span><b>{preview.rejected}</b>rechazados</span></div></div><div className="mapping-row"><div><small>CAMPO ORIGEN</small><b>G · Metres / Metros</b></div><ChevronRight/><div><small>DESTINO DRILLOPS</small><b>metres_drilled</b></div><div><small>CAMPO ORIGEN</small><b>L · Drilling Time</b></div><ChevronRight/><div><small>DESTINO DRILLOPS</small><b>effective_drilling_hours</b></div></div><div className="preview-scroll"><table><thead><tr>{preview.headers.slice(0,8).map((h,i)=><th key={i}>{h||`Columna ${i+1}`}</th>)}</tr></thead><tbody>{preview.rows.slice(0,6).map((r,i)=><tr key={i}>{r.slice(0,8).map((c,j)=><td key={j}>{String(c)||"—"}</td>)}</tr>)}</tbody></table></div><div className="import-actions"><span><ShieldCheck/>Se conservarán valores y fórmulas legacy de coronas cuando estén disponibles.</span><button onClick={()=>setPreview(null)}>Cancelar</button><button className="primary-btn" onClick={()=>setDone(true)}><Database/>{done?`${preview.valid-preview.incomplete} registros importados`:"Importar registros válidos"}</button></div></section>:<section className="panel"><PanelHead title="Historial de importaciones" subtitle="Trabajos auditados por empresa"/><div className="import-history"><div><FileSpreadsheet/><div><b>goldtech_performance_demo.xlsx</b><span>GoldTech Legacy · 284 registros</span></div><span className="status success">COMPLETADO</span><time>02 Ago 2026</time></div><div><FileSpreadsheet/><div><b>survey_SEC42D.csv</b><span>Survey · 15 estaciones</span></div><span className="status success">COMPLETADO</span><time>01 Ago 2026</time></div></div></section>}</>}

const questions=["¿Cuántos metros perforamos? Muéstralo en barras 3D.","Ahora conviértelo a pies.","Grafica el ROP diario como área.","¿Cuáles son las principales causas de NPT?","¿Cuándo terminaríamos el sondeo al rendimiento actual?","Compara el costo de las coronas en USD por pie."];
type AssistantMessage={role:"user"|"assistant";text:string;links?:Array<{label:string;href:string}>;chart?:BiChartSpec|null;facts?:Array<{label:string;value:string}>};
function Assistant({tenantId}:{tenantId:TenantId}){
  const [messages,setMessages]=useState<AssistantMessage[]>([{role:"assistant",text:"Hola, soy Drill Assistant BI. Puedo consultar los indicadores autorizados, convertir unidades y construir una gráfica a partir de cada pregunta. ¿Qué quieres analizar?"}]);
  const [query,setQuery]=useState("");
  const [loading,setLoading]=useState(false);
  const [mode,setMode]=useState<"deterministic"|"openai"|"fallback">("deterministic");
  const messagesRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{const container=messagesRef.current;if(container)container.scrollTop=container.scrollHeight},[messages,loading]);
  async function ask(q:string){
    if(!q.trim()||loading)return;
    const history=messages.slice(-8).map(message=>({role:message.role,text:message.text}));
    setMessages(current=>[...current,{role:"user",text:q}]);setQuery("");setLoading(true);
    try{
      const res=await fetch("/api/v1/assistant",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({question:q,tenantId,history})});
      const data=await res.json() as {answer?:string;error?:string;links?:Array<{label:string;href:string}>;chart?:BiChartSpec|null;facts?:Array<{label:string;value:string}>;mode?:"deterministic"|"openai"|"fallback"};
      if(!res.ok)throw new Error(data.error??"Consulta inválida");
      setMode(data.mode??"deterministic");
      setMessages(current=>[...current,{role:"assistant",text:data.answer??"No encontré una respuesta.",links:data.links,chart:data.chart,facts:data.facts}]);
    }catch(error){setMode("fallback");setMessages(current=>[...current,{role:"assistant",text:error instanceof Error?`No pude completar la consulta: ${error.message}.`:"No pude consultar el backend."}]);}
    setLoading(false);
  }
  return <div className="assistant-layout"><aside className="assistant-prompts"><div><Bot/><h3>Preguntas sugeridas</h3><p>Pide un indicador, unidad y tipo de gráfica.</p></div>{questions.map(question=><button key={question} onClick={()=>ask(question)}>{question}<ChevronRight/></button>)}<div className="ai-safety"><ShieldCheck/><b>Consultas controladas</b><span>El modelo selecciona funciones de solo lectura; los cálculos se ejecutan en el backend y permanecen aislados por tenant.</span></div></aside><section className="chat"><header><div className="bot-avatar"><Sparkles/></div><div><b>Drill Assistant BI</b><span><i/> {mode==="openai"?"OpenAI + funciones controladas":mode==="fallback"?"Motor local de respaldo":"Motor BI determinístico"}</span></div><small>SEC-42D · Extract Services</small></header><div className="messages" ref={messagesRef}>{messages.map((message,index)=><div className={`message ${message.role} ${message.chart?"with-chart":""}`} key={index}>{message.role==="assistant"&&<div className="mini-bot"><Bot/></div>}<div><p>{message.text}</p>{message.facts&&message.facts.length>0&&<div className="message-facts">{message.facts.map(fact=><span key={`${fact.label}-${fact.value}`}><small>{fact.label}</small><b>{fact.value}</b></span>)}</div>}{message.chart&&<div className="message-chart"><header><b>{message.chart.title}</b><span>{message.chart.subtitle}</span></header><BiChart spec={message.chart}/></div>}{message.links&&<div className="message-links">{message.links.map(link=><Link key={`${link.href}-${link.label}`} href={link.href}>{link.label}<ChevronRight/></Link>)}</div>}</div></div>)}{loading&&<div className="message assistant"><div className="mini-bot"><Bot/></div><div className="typing"><i/><i/><i/></div></div>}</div><form onSubmit={event=>{event.preventDefault();ask(query)}}><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Ej.: grafica los metros diarios en pies y columnas 3D…"/><button className="primary-btn" disabled={loading}><Sparkles/>Analizar</button></form><small className="chat-foot">Las respuestas y gráficas usan el mismo motor de métricas del dashboard. La IA interpreta la intención; el backend calcula.</small></section></div>;
}

function Report({tenantId}:{tenantId:TenantId}){
  const dataset=useMemo(()=>getDemoBiDataset(tenantId),[tenantId]);
  const snapshot=useMemo(()=>buildOperationalSnapshot(dataset,undefined,7),[dataset]);
  const recommendation=recommendCrowns(dataset.crowns,{tenantId,diameter:"HQ",hardness:4,fracturing:"high",abrasivity:"high",waterReturn:"partial",priority:"balanced"})[0];
  const maxNpt=Math.max(...snapshot.npt.map(item=>item.hours),1);
  if(!snapshot.hole)return <EmptyTenant/>;
  return <section className="report-page panel"><div className="report-actions"><span className="status success">MÉTRICAS RECONCILIADAS</span><button onClick={()=>window.print()}><Printer/>Imprimir / Guardar PDF</button></div><header className="report-header"><div className="side-brand"><span className="brand-mark"><Gauge/></span><span>DRILLOPS <b>INTELLIGENCE</b></span></div><div><small>REPORTE EJECUTIVO DE SONDEO</small><h2>{snapshot.hole.code} · {snapshot.hole.project}</h2><p>Periodo: {snapshot.period.start} — {snapshot.period.end} · {tenants.find(tenant=>tenant.id===tenantId)?.name}</p></div></header><div className="report-kpis"><div><span>Metros perforados</span><b>{fmt(snapshot.kpis.metres,1)} m</b><small>{fmt(snapshot.kpis.effectiveHours,1)} h efectivas</small></div><div><span>ROP ponderado</span><b>{fmt(snapshot.kpis.rop,2)} m/h</b><small>Metros / horas efectivas</small></div><div><span>Utilización</span><b>{fmt(snapshot.kpis.utilization,1)}%</b><small>Horas efectivas / programadas</small></div><div><span>Costo operativo estimado</span><b>${fmt(snapshot.kpis.operationalCostPerMetre,1)}/m</b><small>Taladro + corona histórica</small></div></div><div className="report-columns"><section><h3>Resumen operacional</h3><p>El sondeo alcanzó {fmt(snapshot.kpis.currentDepth,0)} m de {fmt(snapshot.kpis.targetDepth,0)} m ({fmt(snapshot.kpis.completionPct,1)}%). En el tramo {snapshot.anomaly?.from??"—"}–{snapshot.anomaly?.to??"—"} m, el ROP cambió {fmt(snapshot.anomaly?.ropChangePct??0,1)}% frente a los cinco intervalos previos; es una señal operacional, no una inferencia geológica.</p><h3>Tiempo no productivo · {fmt(snapshot.nptTotal,1)} h</h3>{snapshot.npt.slice(0,4).map(item=><div className="report-bar" key={item.cause}><span>{item.cause}</span><i><b style={{width:`${item.hours/maxNpt*100}%`}}/></i><strong>{fmt(item.hours,1)} h</strong></div>)}</section><section><h3>Rendimiento de coronas</h3><table><thead><tr><th>Corona</th><th>ROP</th><th>USD/m</th><th>Vida</th></tr></thead><tbody>{dataset.crowns.filter(crown=>crown.diameter==="HQ").map(crown=><tr key={crown.id}><td>{crown.product}</td><td>{crown.historicalRop}</td><td>${crown.historicalCost}</td><td>{crown.historicalLife} m</td></tr>)}</tbody></table><h3>Recomendación</h3><div className="report-rec"><Sparkles/><p><b>Balance: {recommendation?.crown.product??"Sin recomendación"}</b><br/>{recommendation?`${recommendation.reasons.slice(0,2).join(". ")}. Confianza ${recommendation.confidence==="medium"?"media":recommendation.confidence}.`:"No hay evidencia suficiente para recomendar."}</p></div></section></div><footer>Generado por DrillOps Intelligence · Fuente {snapshot.source==="demo"?"demo determinística":"base SQL"} · {new Date(snapshot.generatedAt).toLocaleString("es-EC",{timeZone:"America/Guayaquil"})}</footer></section>;
}

function Billing({tenantId}:{tenantId:TenantId}){const initial=tenants.find(t=>t.id===tenantId)?.plan??"Starter";const [current,setCurrent]=useState(initial),[annual,setAnnual]=useState(true),[notice,setNotice]=useState("");const plans=[{name:"Starter",m:249,a:199,desc:"Para iniciar captura operacional",features:["5 usuarios","2 taladros","3 proyectos","100 consultas IA"]},{name:"Professional",m:599,a:479,desc:"Inteligencia para operaciones activas",features:["25 usuarios","10 taladros","Proyectos ilimitados","Bit Advisor + IA"]},{name:"Enterprise",m:0,a:0,desc:"Gobierno y escalabilidad multi-sitio",features:["Usuarios y taladros flexibles","SSO y auditoría avanzada","Integraciones y sensores","Soporte dedicado"]}];return <>{notice&&<RecordNotice>{notice}</RecordNotice>}<div className="demo-billing"><Sparkles/><div><b>Modo demostración</b><span>Puedes cambiar de plan sin pago. La arquitectura BillingProvider está lista para integrar un proveedor real.</span></div><span className="status warning">DEMO_MODE</span></div><div className="billing-toggle"><button className={!annual?"active":""} onClick={()=>setAnnual(false)}>Mensual</button><button className={annual?"active":""} onClick={()=>setAnnual(true)}>Anual <span>Ahorra 20%</span></button></div><div className="plans">{plans.map(p=><article key={p.name} className={current===p.name?"current":""}>{current===p.name&&<span className="current-label">PLAN ACTUAL</span>}<h3>{p.name}</h3><p>{p.desc}</p><div className="price">{p.m?<><b>${annual?p.a:p.m}</b><span>USD / mes<br/>{annual?"facturado anual":"facturado mensual"}</span></>:<b>Hablemos</b>}</div><ul>{p.features.map(f=><li key={f}><CheckCircle2/>{f}</li>)}</ul><button disabled={current===p.name} className={current===p.name?"":"primary-btn"} onClick={()=>{setCurrent(p.name);setNotice(`Plan ${p.name} activado en modo demostración`)}}>{current===p.name?"Plan actual":p.name==="Enterprise"?"Activar demo Enterprise":"Cambiar plan"}</button></article>)}</div><section className="panel usage"><PanelHead title="Uso del periodo" subtitle="1–31 agosto 2026"/><div><Usage label="Usuarios" used={8} total={25}/><Usage label="Taladros" used={2} total={10}/><Usage label="Importaciones" used={3} total={25}/><Usage label="Consultas IA" used={62} total={1000}/></div></section></>}
function Usage({label,used,total}:{label:string;used:number;total:number}){return <div><span>{label}</span><i><b style={{width:`${used/total*100}%`}}/></i><strong>{used} / {total}</strong></div>}

function SettingsScreen(){const tabs=["General","Usuarios y roles","Feature flags","IA y privacidad","Auditoría"] as const;const [tab,setTab]=useState<(typeof tabs)[number]>("General"),[saved,setSaved]=useState(false),[length,setLength]=useState(3),[modules,setModules]=useState([true,false,false]);const switchTab=(value:(typeof tabs)[number])=>{setTab(value);setSaved(false)};return <div className="settings-grid"><nav>{tabs.map(value=><button key={value} className={tab===value?"active":""} onClick={()=>switchTab(value)}>{value}</button>)}</nav><section className="panel settings-form">{tab==="General"&&<><h3>Configuración general</h3><p>Preferencias aisladas para Extract Services Demo.</p><label>Nombre comercial<input defaultValue="Extract Services Demo"/></label><div className="form-row"><label>Moneda<select><option>USD — Dólar estadounidense</option></select></label><label>Turno por defecto<select><option>12 horas</option><option>8 horas</option></select></label></div><label>Longitud de intervalo por defecto<div className="segmented"><button className={length===3?"active":""} onClick={()=>{setLength(3);setSaved(false)}}>3.0 m</button><button className={length===1.5?"active":""} onClick={()=>{setLength(1.5);setSaved(false)}}>1.5 m</button></div></label></>}{tab==="Usuarios y roles"&&<><h3>Usuarios y roles</h3><p>Acceso efectivo de la empresa actual.</p><div className="settings-list"><div><Users/><span><b>Andrea Plataforma</b><small>platform_admin · acceso total</small></span><span className="status success">ACTIVO</span></div><div><Users/><span><b>Supervisión Extract</b><small>supervisor · operación y reportes</small></span><span className="status success">ACTIVO</span></div><div><Users/><span><b>Operación Extract</b><small>operator · captura operacional</small></span><span className="status success">ACTIVO</span></div></div></>}{tab==="Feature flags"&&<><h3>Feature flags</h3><p>Activa módulos en este tenant.</p>{[["Drill Assistant","AI_ENABLED","El asistente accede solo a funciones autorizadas."],["Geología opcional","GEOLOGY_ENABLED","Desactivada: no se almacena litología confidencial."],["Sensor ingestion","SENSOR_INGESTION","Preparado para futura telemetría."]].map((x,i)=><div className="toggle-row" key={x[0]}><div><b>{x[0]}</b><code>{x[1]}</code><span>{x[2]}</span></div><button aria-label={`${modules[i]?"Desactivar":"Activar"} ${x[0]}`} className={modules[i]?"on":""} onClick={()=>{setModules(current=>current.map((value,index)=>index===i?!value:value));setSaved(false)}}><i/></button></div>)}</>}{tab==="IA y privacidad"&&<><h3>IA y privacidad</h3><p>Controles aplicados al asistente de business intelligence.</p><div className="privacy-card"><ShieldCheck/><div><b>Consultas de solo lectura</b><span>El modelo no ejecuta SQL libre; selecciona funciones autorizadas y siempre incluye el tenant activo.</span></div></div><div className="privacy-card"><Database/><div><b>Sin mezcla entre empresas</b><span>Las APIs verifican la sesión y el tenant antes de recuperar métricas.</span></div></div></>}{tab==="Auditoría"&&<><h3>Auditoría</h3><p>Actividad reciente de configuración.</p><div className="settings-list"><div><Save/><span><b>Preferencias revisadas</b><small>Andrea Plataforma · hoy</small></span><span className="status success">OK</span></div><div><Bot/><span><b>Drill Assistant habilitado</b><small>Configuración inicial · 02 Ago 2026</small></span><span className="status success">OK</span></div></div></>}<button className="primary-btn" onClick={()=>setSaved(true)}><Save/>{saved?"Cambios guardados":"Guardar cambios"}</button></section></div>}

function Tenants(){const [rows,setRows]=useState(()=>tenants.map((tenant,index)=>({...tenant,billing:index===0?"Anual":"Mensual",users:[8,4,15][index],rigs:[2,1,4][index],ai:["62 / 1000","18 / 100","211 / flexible"][index],renewal:["01 Sep 2026","18 Ago 2026","14 Sep 2026"][index]}))),[open,setOpen]=useState(false),[notice,setNotice]=useState("");const [form,setForm]=useState({name:"",slug:"",plan:"Starter",status:"trial" as "active"|"trial"});function submit(){if(rows.some(row=>normalize(row.slug)===normalize(form.slug.trim()))){return}setRows(current=>[...current,{id:`tenant-${Date.now()}` as TenantId,name:form.name.trim(),slug:form.slug.trim().toLowerCase(),plan:form.plan,status:form.status,color:"#56c7ff",billing:"Mensual",users:1,rigs:0,ai:"0 / 100",renewal:"Por definir"}]);setNotice(`Empresa ${form.name.trim()} creada en modo staging`);setForm({name:"",slug:"",plan:"Starter",status:"trial"});setOpen(false)}return <>{notice&&<RecordNotice>{notice}</RecordNotice>}<div className="platform-summary"><ShieldCheck/><div><b>Vista de Platform Admin</b><span>Cada empresa opera en un perímetro de datos independiente. El selector nunca mezcla registros.</span></div><button className="primary-btn" onClick={()=>{setOpen(true);setNotice("")}}><Plus/>Nueva empresa</button></div><section className="panel table-panel"><table><thead><tr><th>Empresa</th><th>Plan</th><th>Facturación</th><th>Usuarios</th><th>Taladros</th><th>Uso IA</th><th>Estado</th><th>Renovación</th></tr></thead><tbody>{rows.map(t=><tr key={t.id}><td><div className="tenant-cell"><span style={{background:t.color}}>{t.name.slice(0,2).toUpperCase()}</span><div><b>{t.name}</b><small>{t.slug}</small></div></div></td><td>{t.plan}</td><td>{t.billing}</td><td>{t.users}</td><td>{t.rigs}</td><td>{t.ai}</td><td><span className={`status ${t.status==="active"?"success":"warning"}`}>{t.status==="active"?"ACTIVO":"TRIAL"}</span></td><td>{t.renewal}</td></tr>)}</tbody></table></section><div className="tenant-proof"><div><Building2/><b>{rows.length}</b><span>empresas</span></div><div><Users/><b>{rows.reduce((sum,row)=>sum+row.users,0)}</b><span>usuarios aislados</span></div><div><Database/><b>0</b><span>registros compartidos</span></div><div><ShieldCheck/><b>100%</b><span>consultas con tenant_id</span></div></div><RecordModal open={open} title="Crear empresa" description="Configura el perímetro inicial de una nueva organización." submitLabel="Crear empresa" onClose={()=>setOpen(false)} onSubmit={event=>{event.preventDefault();submit()}}><div className="record-grid"><label>Nombre comercial<input autoFocus required value={form.name} onChange={event=>setForm({...form,name:event.target.value})}/></label><label>Slug<input required pattern="[a-z0-9-]+" placeholder="empresa-minera" value={form.slug} onChange={event=>setForm({...form,slug:event.target.value})}/></label><label>Plan<select value={form.plan} onChange={event=>setForm({...form,plan:event.target.value})}><option>Starter</option><option>Professional</option><option>Enterprise</option></select></label><label>Estado<select value={form.status} onChange={event=>setForm({...form,status:event.target.value as "active"|"trial"})}><option value="trial">Trial</option><option value="active">Activo</option></select></label></div></RecordModal></>}
